import os, re, json

# Load grids from session log
def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    content = open(path).read().replace('\\n', '\n')
    G = {}

    # Parse demo inputs/outputs and test input
    lines = content.split('\n')
    in_grid = None
    grid_name = None

    for line in lines:
        if 'Demo pair' in line or 'Test input' in line:
            # Save previous grid if any
            if in_grid is not None and grid_name is not None:
                G[grid_name] = in_grid

            if 'Test input' in line:
                grid_name = f'test_{os.path.basename(d)}'
                in_grid = []
            else:
                # Extract dimensions
                match = re.search(r'Demo pair \d+ (?:input|output)\s*\((\d+)x(\d+)\)', line)
                if match:
                    h, w = int(match.group(1)), int(match.group(2))
                    grid_name = f'demo_{os.path.basename(d)}_{match.group(0)}'
                    in_grid = []
            continue

        if in_grid is not None:
            parts = line.split()
            if len(parts) == 15 and all(p.isdigit() for p in parts):
                in_grid.append([int(x) for x in parts])

    # Save last grid
    if in_grid is not None and grid_name is not None:
        G[grid_name] = in_grid

    return G

