    """Find all unique non-zero 2x3 regions"""
    h, w = len(grid), len(grid[0])
    seen = {}

    for i in range(h - 1):
        for j in range(w - 2):
            # Extract 2x3 region
            region = []
            for r in range(2):
                row = grid[i+r][j:j+3]
                if all(x != 0 for x in row):
                    region.append(tuple(row))

            if len(region) == 2 and region[0][0] != 0:
                key = tuple(zip(*region))
                seen.setdefault(key, []).append((i, j))

    return seen

